export class Stack<T> {
  private readonly items: T[] = [];

  constructor(readonly capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError("capacity must be a positive integer");
    }
  }

  push(item: T): void {
    if (this.items.length >= this.capacity) {
      throw new Error("stack overflow");
    }
    this.items.push(item);
  }

  pop(): T {
    const item = this.items.pop();
    if (item === undefined) throw new Error("stack underflow");
    return item;
  }

  peek(): T {
    const item = this.items[this.items.length - 1];
    if (item === undefined) throw new Error("stack underflow");
    return item;
  }

  get size(): number {
    return this.items.length;
  }
}

export class Ring<T> {
  private readonly buf: (T | undefined)[];
  private head = 0;
  private len = 0;

  constructor(readonly capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError("capacity must be a positive integer");
    }
    this.buf = new Array(capacity);
  }

  enqueue(item: T): void {
    if (this.len >= this.capacity) throw new Error("ring overflow");
    this.buf[(this.head + this.len) % this.capacity] = item;
    this.len++;
  }

  dequeue(): T {
    if (this.len === 0) throw new Error("ring underflow");
    const item = this.buf[this.head] as T;
    this.buf[this.head] = undefined;
    this.head = (this.head + 1) % this.capacity;
    this.len--;
    return item;
  }

  peek(): T {
    if (this.len === 0) throw new Error("ring underflow");
    return this.buf[this.head] as T;
  }

  get size(): number {
    return this.len;
  }
}

